// AUD-02: Audit trails from another tenant are invisible.
// Note: the title does not include VI_SECRET_KEY. Writing a secret from backend/.env into a
// test title would commit it to source control and publish it in test reports. Trace runs by
// the @AUD-02 tag instead.
// Assumption: a Globex persona exists in ./fixtures/users. Adjust the persona key if it differs.
import { expectStatus, expect, test, uniqueName } from "../fixtures";

test.describe("vendor audit trail tenant isolation", () => {
  test(
    "audit trail of a vendor in another tenant returns 404 to a Northwind member",
    { tag: "@AUD-02" },
    async ({ apiAs, factory }) => {
      // Arrange: a vendor owned by the Globex Procurement tenant.
      const globex = await apiAs("globex");
      const vendorName = uniqueName("Globex Audit Vendor");
      const created = await globex.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "services",
          contact_email: `${vendorName.toLowerCase().replace(/[^a-z0-9]+/g, "")}@example.test`,
        },
      });
      const vendor = await expectStatus<{ id: string }>(created, 201);
      expect(vendor.id).toBeTruthy();

      // Act: a Northwind member requests that vendor's audit trail.
      const member = await apiAs("member");
      const response = await member.get(`/api/vendors/${vendor.id}/audit`);

      // Assert: the other tenant's trail is not visible.
      await expectStatus(response, 404);
    },
  );
});
